    53→	let statusCounts = $derived.by(() => {
    54→		const counts: Record<string, number> = {};
    55→		for (const plan of plans) {
    56→			counts[plan.status] = (counts[plan.status] ?? 0) + 1;
    57→		}
    58→		return counts;
    59→	});
    60→
    61→	// ── Lifecycle ──
    62→	onMount(async () => {
    63→		await loadData();
    64→
    65→		if (!isStaticMode()) {
    66→			// Plan progress is derived from task statuses, so subscribe to tasks:updates
    67→			// to refresh when task status changes (e.g., task completed → plan progress updates)
    68→			subscribe(['tasks:updates']);
    69→			on('tasks:updates', handleUpdate);
    70→		}
    71→	});
    72→
    73→	onDestroy(() => {
    74→		if (!isStaticMode()) {
    75→			off('tasks:updates', handleUpdate);
    76→			unsubscribe(['tasks:updates']);
    77→		}
    78→	});
    79→
    80→	// Reload on project change
    81→	$effect(() => {
    82→		const version = getProjectVersion();
    83→		if (version > 0) {
    84→			loadData();
    85→		}
    86→	});
    87→
    88→	// ── Data loading ──
    89→	async function loadData() {
    90→		try {
    91→			loading = true;
    92→			error = '';
    93→			const response = await fetchPlans();
    94→			plans = response.items;
    95→		} catch (err) {
    96→			error = err instanceof Error ? err.message : 'Failed to load plans';
    97→		} finally {
    98→			loading = false;
    99→		}
   100→	}
   101→
   102→	// ── WebSocket handler ──
   103→	function handleUpdate() {
   104→		loadData();
   105→	}
   106→
   107→	// ── Formatting ──
   108→	function formatDate(dateString: string): string {
   109→		const date = new Date(dateString);
   110→		const now = new Date();
   111→		const diffMs = now.getTime() - date.getTime();
   112→		const diffMins = Math.floor(diffMs / 60000);
   113→		const diffHours = Math.floor(diffMs / 3600000);
   114→		const diffDays = Math.floor(diffMs / 86400000);
   115→
   116→		if (diffMins < 1) return 'just now';
   117→		if (diffMins < 60) return `${diffMins}m ago`;
   118→		if (diffHours < 24) return `${diffHours}h ago`;
   119→		if (diffDays < 7) return `${diffDays}d ago`;
   120→
   121→		return date.toLocaleDateString();
   122→	}
   123→
   124→	// AC: @ui-plans-view ac-1 — Progress percentage from task completion status
   125→	function progressPercent(plan: PlanSummary): number {
   126→		if (plan.task_progress.total === 0) return 0;
   127→		return Math.round((plan.task_progress.completed / plan.task_progress.total) * 100);
   128→	}
   129→</script>
