"use client";

import type { GenerationJob, GenerateParams, GenerationErrorCode } from "@imgen/shared";
import "./failed-job-card.css";

/**
 * Error category configuration
 * AC: @categorized-error-messages - Maps error codes to user-friendly display
 */
interface ErrorConfig {
  icon: React.ReactNode;
  message: string;
  isRetryable: boolean;
}

function getRenderableErrorDetail(detail?: string): string | null {
  if (!detail) return null;
  const normalized = detail.replace(/\s+/g, " ").trim();
  if (!normalized) return null;
  if (normalized.length > 240) return null;
  return normalized;
}

/**
 * Get icon component for error type
 * Each error category has a distinct visual indicator
 */
function getErrorIcon(
  type: "content" | "rate" | "timeout" | "config" | "generic",
): React.ReactNode {
  switch (type) {
    // AC: @categorized-error-messages ac-1 - Content warning icon
    case "content":
      return (
        <svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          aria-hidden="true"
        >
          <path d="M12 9v4M12 17h.01" />
          <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z" />
        </svg>
      );
    // AC: @categorized-error-messages ac-2 - Clock/throttle icon for rate limiting
    case "rate":
      return (
        <svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="10" />
          <path d="M12 6v6l4 2" />
        </svg>
      );
    // AC: @categorized-error-messages ac-3 - Timeout/unavailable icon
    case "timeout":
      return (
        <svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="10" />
          <path d="M12 6v6" />
          <path d="M16.24 16.24l-2.83-2.83" />
          <path d="M6 18L18 6" strokeWidth="2" />
        </svg>
      );
    // AC: @categorized-error-messages ac-4 - Configuration icon for invalid params
    case "config":
      return (
        <svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="3" />
          <path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-2 2 2 2 0 01-2-2v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06a1.65 1.65 0 00.33-1.82 1.65 1.65 0 00-1.51-1H3a2 2 0 01-2-2 2 2 0 012-2h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06a1.65 1.65 0 001.82.33H9a1.65 1.65 0 001-1.51V3a2 2 0 012-2 2 2 0 012 2v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06a1.65 1.65 0 00-.33 1.82V9a1.65 1.65 0 001.51 1H21a2 2 0 012 2 2 2 0 01-2 2h-.09a1.65 1.65 0 00-1.51 1z" />
        </svg>
      );
    // AC: @categorized-error-messages ac-5 - Generic error icon
    default:
      return (
        <svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="10" />
          <path d="M12 8v4M12 16v0.5" />
        </svg>
      );
  }
}

/**
 * Get error configuration based on error code
 * AC: @categorized-error-messages - Maps error codes to display configuration
 */
function getErrorConfig(errorCode?: GenerationErrorCode, fallbackMessage?: string): ErrorConfig {
  switch (errorCode) {
    // AC: @categorized-error-messages ac-1 - Content policy violation
    case "content_policy_violation":
      return {
        icon: getErrorIcon("content"),
        message:
          "Your prompt was flagged by our content policy. Please modify your prompt and try again.",
        isRetryable: false,
      };

    // AC: @categorized-error-messages ac-2 - Rate limiting
    case "rate_limited":
      return {
        icon: getErrorIcon("rate"),
        message: "Service is busy. Please try again in a moment.",
        isRetryable: true,
      };

    // AC: @categorized-error-messages ac-3 - Timeout
    case "timeout":
    case "stale_timeout":
      return {
        icon: getErrorIcon("timeout"),
        message: "Generation timed out. Please try again.",
        isRetryable: true,
      };

    // AC: @categorized-error-messages ac-3 - Model unavailable
    case "model_unavailable":
      return {
        icon: getErrorIcon("timeout"),
        message: "This model is temporarily unavailable. Please try again or choose another model.",
        isRetryable: true,
      };

    // AC: @categorized-error-messages ac-4 - Invalid parameters
    case "invalid_params":
      return {
        icon: getErrorIcon("config"),
        message:
          fallbackMessage ||
          "There was an issue with your parameters. Please adjust and try again.",
        isRetryable: false,
      };

    // AC: @categorized-error-messages ac-5 - Provider error, dispatch failure, etc.
    case "provider_error":
    case "dispatch_failed":
    case "all_images_failed":
    case "partial_failure":
    default:
      // For provider errors, log detailed error but show generic message
      if (errorCode === "provider_error" && fallbackMessage) {
        console.error("[FailedJobCard] Provider error details:", fallbackMessage);
      }
      return {
        icon: getErrorIcon("generic"),
        message: "Something went wrong. Please try again.",
        isRetryable: true,
      };
  }
}

interface FailedJobCardProps {
  job: GenerationJob;
  /** AC: @gallery-home ac-7 - Retry callback pre-fills generation bar with failed job params */
  onRetry: (params: GenerateParams) => void;
  /** AC: @gallery-home ac-12, ac-14 - Dismiss callback to remove failed job from view */
  onDismiss?: (jobId: string) => void;
  className?: string;
}

/**
 * Card for displaying a failed generation job with categorized error messages.
 * AC: @gallery-home ac-7 - Failed job card with retry functionality
 * AC: @gallery-home ac-12 - Dismiss button to remove failed job from view
 * AC: @gallery-home ac-14 - Dismissed jobs are marked in database and don't reappear
 * AC: @categorized-error-messages - Maps error codes to user-friendly messages with distinct icons
 *
 * @example
 * ```tsx
 * <FailedJobCard
 *   job={failedJob}
 *   onRetry={(params) => {
 *     // Pre-fill generation bar with params
 *     setGenerationBarValue(params);
 *   }}
 *   onDismiss={(jobId) => {
 *     // Mark job as dismissed in database
 *     dismissJob(jobId);
 *   }}
 * />
 * ```
 */
export function FailedJobCard({ job, onRetry, onDismiss, className }: FailedJobCardProps) {
  const promptPreview = job.prompt.length > 40 ? `${job.prompt.slice(0, 40)}...` : job.prompt;

  // AC: @categorized-error-messages - Get error configuration based on error code
  const errorConfig = getErrorConfig(job.errorCode, job.error);
  const errorDetail = getRenderableErrorDetail(job.errorDetail);

  const handleRetry = () => {
    onRetry({
      prompt: job.prompt,
      model: job.model,
      count: job.count,
    });
  };

  const handleDismiss = () => {
    onDismiss?.(job.id);
  };

  // Determine CSS modifier class based on error type
  const errorTypeClass =
    job.errorCode === "content_policy_violation" ? " ds-failed-job--content" : "";

  return (
    <div
      className={`ds-failed-job${errorTypeClass}${className ? ` ${className}` : ""}`}
      data-testid="failed-job-card"
      data-error-code={job.errorCode || "unknown"}
    >
      {/* AC: @gallery-home ac-12 - Dismiss button */}
      {onDismiss && (
        <button
          type="button"
          className="ds-failed-job-dismiss"
          onClick={handleDismiss}
          aria-label="Dismiss failed job"
          data-testid="failed-job-dismiss"
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 16 16"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
          >
            <path d="M12 4L4 12M4 4l8 8" />
          </svg>
        </button>
      )}

      <div className="ds-failed-job-inner">
        {/* AC: @categorized-error-messages - Error type icon */}
        <div
          className="ds-failed-job-icon"
          data-testid="failed-job-icon"
          data-icon-type={job.errorCode || "generic"}
        >
          {errorConfig.icon}
        </div>

        {/* Error content */}
        <div className="ds-failed-job-content">
          <p className="ds-failed-job-prompt font-[family-name:var(--font-design-primary)]">
            {promptPreview}
          </p>
          <p
            className="ds-failed-job-error font-[family-name:var(--font-design-mono)]"
            data-testid="failed-job-error-message"
          >
            {errorConfig.message}
          </p>
          {errorDetail && (
            <p
              className="ds-failed-job-error-detail font-[family-name:var(--font-design-mono)]"
              data-testid="failed-job-error-detail"
            >
              {errorDetail}
            </p>
          )}
        </div>

        {/* AC: @categorized-error-messages - Retry button only for retryable errors */}
        {errorConfig.isRetryable && (
          <button
            className="ds-failed-job-retry"
            onClick={handleRetry}
            aria-label="Retry generation"
            type="button"
            data-testid="failed-job-retry"
          >
            <svg
              width="16"
              height="16"
              viewBox="0 0 16 16"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
            >
              <path d="M2 8a6 6 0 0 1 10.45-4M14 8a6 6 0 0 1-10.45 4" />
              <path d="M12 4h2.5V1.5M4 12H1.5v2.5" />
            </svg>
            <span>Retry</span>
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import type { GalleryImage } from "@imgen/shared";
import { useScrollReveal } from "../../hooks/use-scroll-reveal";
import "./gallery-card.css";

/**
 * Format relative time since a date (e.g., "2h ago")
 * AC: @gallery-home ac-8 - Time since generation on card
 */
function formatRelativeTime(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSecs = Math.floor(diffMs / 1000);
  const diffMins = Math.floor(diffSecs / 60);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffSecs < 60) return "now";
  if (diffMins < 60) return `${diffMins}m`;
  if (diffHours < 24) return `${diffHours}h`;
  if (diffDays < 7) return `${diffDays}d`;
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

interface GalleryCardProps {
  image: GalleryImage;
  onClick: () => void;
  className?: string;
  /** AC: @gallery-home ac-5 - Whether this card's batch siblings are being hovered */
  isBatchHighlighted?: boolean;
  /** AC: @gallery-home ac-5 - Callback when mouse enters (for batch hover highlighting) */
  onMouseEnter?: () => void;
  /** AC: @gallery-home ac-5 - Callback when mouse leaves */
  onMouseLeave?: () => void;
  /** AC: @image-deletion ac-4 - Whether selection mode is active */
  isSelectionMode?: boolean;
  /** AC: @image-deletion ac-4 - Whether this card is selected */
  isSelected?: boolean;
  /** AC: @image-deletion ac-4 - Callback when selection changes */
  onSelectionToggle?: (imageId: string) => void;
}

/**
 * Masonry gallery image card with scroll-reveal, hover overlay, keyboard activation,
 * batch indicator, and time since generation.
 *
 * AC: @gallery-home ac-5 - Batch indicator and hover highlighting
 * AC: @gallery-home ac-8 - Time since generation display
 *
 * @example
 * ```tsx
 * <GalleryCard
 *   image={image}
 *   onClick={() => openLightbox(image.id)}
 *   isBatchHighlighted={hoveredBatchId === image.batchId}
 *   onMouseEnter={() => setHoveredBatchId(image.batchId)}
 *   onMouseLeave={() => setHoveredBatchId(null)}
 * />
 * ```
 */
export function GalleryCard({
  image,
  onClick,
  className,
  isBatchHighlighted,
  onMouseEnter,
  onMouseLeave,
  isSelectionMode,
  isSelected,
  onSelectionToggle,
}: GalleryCardProps) {
  const { ref, isVisible } = useScrollReveal(0.1);
  const [imgError, setImgError] = useState(false);
  const hasBatchSiblings = image.batchSiblingIds && image.batchSiblingIds.length > 0;

  const handleClick = () => {
    if (isSelectionMode && onSelectionToggle) {
      onSelectionToggle(image.id);
    } else {
      onClick();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      handleClick();
    }
  };

  // Build class names
  const cardClasses = [
    "ds-gallery-card",
    isVisible && "ds-gallery-card-visible",
    isBatchHighlighted && "ds-batch-highlighted",
    isSelectionMode && "ds-gallery-card-selectable",
    isSelected && "ds-gallery-card-selected",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div
      ref={ref}
      className={cardClasses}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      role="button"
      tabIndex={0}
      aria-label={`View: ${image.prompt.slice(0, 60)}`}
      data-testid="gallery-card"
      data-image-id={image.id}
    >
      <div className="ds-gallery-card-inner">
        <div
          className="ds-gallery-card-img-wrap"
          style={{
            aspectRatio: image.aspectRatio
              ? image.aspectRatio.replace(":", " / ")
              : `${image.width} / ${image.height}`,
          }}
        >
          {!imgError && image.url ? (
            <Image
              src={image.url}
              alt={image.prompt}
              fill
              sizes="(max-width: 640px) 100vw, (max-width: 768px) 50vw, (max-width: 1280px) 33vw, 25vw"
              style={{ objectFit: "cover" }}
              onError={() => setImgError(true)}
            />
          ) : (
            <div className="ds-gallery-card-fallback">
              <span className="ds-gallery-card-fallback-text font-[family-name:var(--font-design-mono)]">
                {image.prompt}
              </span>
            </div>
          )}

          {/* AC: @gallery-home ac-5 - Batch indicator dot */}
          {hasBatchSiblings && (
            <div
              className="ds-gallery-card-batch-indicator"
              aria-label={`Part of batch with ${image.batchSiblingIds!.length} images`}
              data-testid="gallery-card-batch-indicator"
            />
          )}

          {/* AC: @draft-generation-mode ac-3 - Draft badge for draft images */}
          {image.isDraft && (
            <div className="ds-gallery-card-draft-badge" data-testid="gallery-card-draft-badge">
              Draft
            </div>
          )}

          {/* AC: @image-deletion ac-4 - Selection checkbox in selection mode */}
          {isSelectionMode && (
            <div
              className={`ds-gallery-card-select-check ${isSelected ? "ds-active" : ""}`}
              data-testid="gallery-card-select-check"
              aria-label={isSelected ? "Deselect image" : "Select image"}
            >
              {isSelected && (
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 14 14"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                >
                  <path d="M2.5 7l3 3 6-6" />
                </svg>
              )}
            </div>
          )}
        </div>

        <div className="ds-gallery-card-overlay">
          <p className="ds-gallery-card-prompt font-[family-name:var(--font-design-primary)]">
            {image.prompt}
          </p>
          {/* AC: @gallery-home ac-8 - Model name, truncated prompt, time since generation */}
          <span
            className="ds-gallery-card-meta font-[family-name:var(--font-design-mono)]"
            data-testid="gallery-card-meta"
          >
            <span data-testid="gallery-card-model">{image.modelDisplayName}</span>
            <span> &middot; </span>
            <span data-testid="gallery-card-time">{formatRelativeTime(image.createdAt)}</span>
          </span>
        </div>
      </div>
    </div>
  );
}

