    75→			off('tasks:updates', handleUpdate);
    76→			unsubscribe(['tasks:updates']);
    77→		}
    78→	});
    79→
    80→	// Reload on project change
    81→	$effect(() => {
    82→		const version = getProjectVersion();
    83→		if (version > 0) {
    84→			loadData();
    85→		}
    86→	});
    87→
    88→	// ── Data loading ──
