    16→		AccordionItem,
    17→		AccordionTrigger
    18→	} from '$lib/components/ui/accordion';
    19→	import { Skeleton } from '$lib/components/ui/skeleton';
    20→	import ReferenceLink from '$lib/components/ReferenceLink.svelte';
    21→	import { fetchItem, fetchItemTasks } from '$lib/api';
    22→	import { CheckCircle, XCircle, HelpCircle } from 'lucide-svelte';
    23→
    24→	interface Props {
    25→		ref: string | null;
    26→		open: boolean;
    27→	}
    28→
    29→	let { ref, open = $bindable(false) }: Props = $props();
    30→
    31→	let item = $state<ItemDetail | null>(null);
    32→	let linkedTasks = $state<TaskSummary[]>([]);
    33→	let loading = $state(false);
    34→	let error = $state<string | null>(null);
    35→
    36→	async function loadItem(itemRef: string) {
    37→		loading = true;
    38→		error = null;
    39→		try {
    40→			// Fetch item details
    41→			item = await fetchItem(itemRef);
    42→
    43→			// Fetch linked tasks
    44→			// AC: @web-dashboard ac-13
    45→			const tasksResponse = await fetchItemTasks(itemRef);
    46→			linkedTasks = tasksResponse.items;
    47→		} catch (err) {
    48→			error = err instanceof Error ? err.message : 'Failed to load item';
    49→			item = null;
    50→			linkedTasks = [];
    51→		} finally {
    52→			loading = false;
    53→		}
    54→	}
    55→
    56→	$effect(() => {
    57→		if (ref && open) {
    58→			loadItem(ref);
    59→		}
    60→	});
    61→
    62→	function getStatusColor(status: string): string {
    63→		const colors: Record<string, string> = {
    64→			pending: 'bg-status-pending text-status-pending-fg',
    65→			in_progress: 'bg-status-in-progress text-status-in-progress-fg',
    66→			pending_review: 'bg-status-pending-review text-status-pending-review-fg',
    67→			needs_work: 'bg-status-needs-work text-status-needs-work-fg',
    68→			blocked: 'bg-status-blocked text-status-blocked-fg',
    69→			completed: 'bg-status-completed text-status-completed-fg',
    70→			cancelled: 'bg-status-cancelled text-status-cancelled-fg'
    71→		};
    72→		return colors[status] || 'bg-status-cancelled text-status-cancelled-fg';
    73→	}
    74→
    75→	function formatStatus(status: string): string {
    76→		const labels: Record<string, string> = {
    77→			pending: 'Pending',
    78→			in_progress: 'In Progress',
    79→			pending_review: 'Pending Review',
    80→			needs_work: 'Needs Work',
    81→			blocked: 'Blocked',
    82→			completed: 'Completed',
    83→			cancelled: 'Cancelled'
    84→		};
    85→		return labels[status] || status;
    86→	}
    87→</script>
    88→
    89→<Sheet bind:open>
    90→	<SheetContent class="sm:max-w-2xl overflow-y-auto" data-testid="spec-detail-panel">
    91→		{#if loading}
    92→			<div class="space-y-4">
    93→				<Skeleton class="h-8 w-3/4" />
    94→				<Skeleton class="h-4 w-full" />
    95→				<Skeleton class="h-4 w-full" />
    96→				<Skeleton class="h-4 w-2/3" />
    97→			</div>
    98→		{:else if error}
    99→			<div class="flex flex-col gap-4">
   100→				<SheetHeader>
   101→					<SheetTitle>Error</SheetTitle>
   102→				</SheetHeader>
   103→				<p class="text-destructive">{error}</p>
   104→			</div>
   105→		{:else if item}
   106→			<div class="flex flex-col gap-6">
   107→				<SheetHeader>
   108→					<div class="flex items-center gap-2">
   109→						<!-- AC: @web-dashboard ac-12 - Title and type -->
   110→						<Badge data-testid="implementation-status">{item.type}</Badge>
   111→						<SheetTitle data-testid="spec-title">{item.title}</SheetTitle>
   112→					</div>
   113→					{#if item.description}
   114→						<SheetDescription data-testid="spec-description">{item.description}</SheetDescription>
   115→					{/if}
   116→				</SheetHeader>
   117→
   118→				<!-- Tags -->
   119→				{#if item.tags.length > 0}
   120→					<div>
   121→						<h3 class="text-sm font-semibold mb-2">Tags</h3>
   122→						<div class="flex flex-wrap gap-1">
   123→							{#each item.tags as tag}
   124→								<Badge variant="outline">{tag}</Badge>
   125→							{/each}
   126→						</div>
   127→					</div>
   128→				{/if}
   129→
   130→				<!-- AC: @web-dashboard ac-12, ac-15 - Acceptance Criteria (GWT format) -->
   131→				{#if item.acceptance_criteria && item.acceptance_criteria.length > 0}
   132→					<div data-testid="acceptance-criteria">
   133→						<h3 class="text-sm font-semibold mb-2">Acceptance Criteria</h3>
   134→						<Accordion type="multiple" class="w-full">
   135→							{#each item.acceptance_criteria as ac, i}
   136→								<AccordionItem value={ac._ulid} data-testid="ac-item">
   137→									<AccordionTrigger data-testid="ac-expand-toggle">
   138→										<span class="text-sm" data-testid="ac-given">AC-{i + 1}: {ac.given}</span>
   139→									</AccordionTrigger>
   140→									<AccordionContent>
   141→										<div class="space-y-2 text-sm pl-4">
   142→											<div data-testid="ac-given-full">
   143→												<span class="font-medium text-muted-foreground">Given:</span>
   144→												{ac.given}
   145→											</div>
   146→											<div data-testid="ac-when-full">
   147→												<span class="font-medium text-muted-foreground">When:</span>
   148→												{ac.when}
   149→											</div>
   150→											<div data-testid="ac-then-full">
   151→												<span class="font-medium text-muted-foreground">Then:</span>
   152→												{ac.then}
   153→											</div>
   154→											<!-- AC: @web-dashboard ac-15 - Test coverage indicator -->
   155→											<div
   156→												data-testid="test-coverage-indicator"
   157→												class="text-xs mt-2 inline-flex items-center gap-1 {ac.covered === true
   158→													? 'text-green-600 covered'
   159→													: ac.covered === false
   160→														? 'text-amber-600 uncovered'
   161→														: 'text-muted-foreground unknown'}"
   162→											>
   163→												{#if ac.covered === true}
   164→													<CheckCircle class="w-3 h-3" />
   165→													<span>Covered</span>
   166→												{:else if ac.covered === false}
   167→													<XCircle class="w-3 h-3" />
   168→													<span>Not covered</span>
   169→												{:else}
   170→													<HelpCircle class="w-3 h-3" />
   171→													<span>Coverage: Unknown</span>
   172→												{/if}
   173→											</div>
   174→										</div>
   175→									</AccordionContent>
   176→								</AccordionItem>
   177→							{/each}
   178→						</Accordion>
   179→					</div>
   180→				{/if}
   181→
   182→				<!-- AC: @web-dashboard ac-14 - Traits as chips -->
   183→				{#if item.traits && item.traits.length > 0}
   184→					<div data-testid="traits-section">
   185→						<h3 class="text-sm font-semibold mb-2">Traits</h3>
   186→						<div class="flex flex-wrap gap-2">
