   191→								</span>
   192→							{/each}
   193→						</div>
   194→					</div>
   195→				{/if}
   196→
   197→				<!-- AC: @web-dashboard ac-13 - Linked tasks with status -->
   198→				{#if linkedTasks.length > 0}
   199→					<div data-testid="implementation-section">
