   206→									data-testid="linked-task"
   207→								>
   208→									<Badge class={getStatusColor(task.status)} data-testid="task-status-badge"
   209→										>{formatStatus(task.status)}</Badge
   210→									>
   211→									<span class="text-sm flex-1" data-testid="task-title">{task.title}</span>
   212→									{#if task.notes_count > 0}
   213→										<Badge variant="secondary" class="text-xs">{task.notes_count} notes</Badge>
   214→									{/if}
   215→								</a>
   216→							{/each}
   217→						</div>
   218→					</div>
   219→				{:else}
   220→					<div data-testid="implementation-section">
   221→						<h3 class="text-sm font-semibold mb-2">Implementation</h3>
   222→						<p class="text-sm text-muted-foreground">No tasks linked to this spec item yet.</p>
   223→					</div>
   224→				{/if}
   225→			</div>
   226→		{/if}
   227→	</SheetContent>
   228→</Sheet>
   229→
```

