  inbox_ref: string;
  item_snapshot: string;
  status: TriageStatus;
  action?: TriageAction;
  reasoning?: string;
  decided_by?: string;
  evidence_refs: string[];
  override_reasoning?: string;
  override_by?: string;
  override_at?: string;
  acted_at?: string;
  result_ref?: string;
