    44→ * Parse plans from raw YAML payload.
    45→ *
    46→ * Supports the canonical { kynetic_plans, plans } shape and a fallback
    47→ * { plans } shape for older files without version metadata.
    48→ */
    49→function parsePlansFromRaw(raw: unknown): Plan[] {
    50→  const parsed = PlansFileSchema.safeParse(raw);
    51→  if (parsed.success) {
    52→    return parsed.data.plans;
    53→  }
    54→
    55→  if (raw && typeof raw === "object" && "plans" in raw) {
    56→    const fallbackPlans = (raw as { plans?: unknown }).plans;
    57→    if (Array.isArray(fallbackPlans)) {
    58→      const plans: Plan[] = [];
    59→      for (const plan of fallbackPlans) {
    60→        const planResult = PlanSchema.safeParse(plan);
    61→        if (planResult.success) {
    62→          plans.push(planResult.data);
    63→        }
    64→      }
    65→      return plans;
    66→    }
    67→  }
    68→
    69→  return [];
    70→}
    71→
    72→/**
    73→ * Load plans from an explicit file path.
    74→ */
    75→async function loadPlansFromFile(plansPath: string): Promise<Plan[]> {
    76→  const raw = await readYamlFile<unknown>(plansPath);
    77→  return parsePlansFromRaw(raw);
    78→}
    79→
    80→/**
    81→ * Strip runtime metadata before serialization.
    82→ */
    83→function stripPlanMetadata(plan: Plan | LoadedPlan): Plan {
    84→  const { _sourceFile, ...cleanPlan } = plan as LoadedPlan;
    85→  return cleanPlan as Plan;
    86→}
    87→
    88→/**
    89→ * Load all plans from the project.
    90→ * AC: @plan-crud ac-7, ac-31 - listing plans
    91→ */
    92→export async function loadPlans(ctx: KspecContext): Promise<LoadedPlan[]> {
    93→  const plansPath = getPlansFilePath(ctx);
    94→
    95→  try {
    96→    const plans = await loadPlansFromFile(plansPath);
    97→    return plans.map((plan) => ({
    98→      ...plan,
    99→      _sourceFile: plansPath,
   100→    }));
   101→  } catch {
   102→    // File doesn't exist or parse error
   103→    return [];
   104→  }
   105→}
   106→
   107→/**
   108→ * Find a plan by reference (ULID, short ULID, or slug)
   109→ * AC: @plan-crud ac-8 - get plan by reference
   110→ */
   111→export async function findPlanByRef(
   112→  ctx: KspecContext,
   113→  ref: string,
   114→): Promise<LoadedPlan | undefined> {
   115→  const plans = await loadPlans(ctx);
   116→  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;
   117→
   118→  return plans.find(
   119→    (p) =>
   120→      // Match full ULID
   121→      p._ulid === cleanRef ||
   122→      // Match short ULID (prefix)
   123→      p._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()) ||
   124→      // Match any slug
   125→      p.slugs.includes(cleanRef),
   126→  );
   127→}
   128→
   129→/**
   130→ * Create a new plan from input
   131→ * AC: @plan-crud ac-1, ac-2 - creating plans
   132→ */
   133→export function createPlan(input: PlanInput, author?: string): Plan {
   134→  const now = new Date().toISOString();
   135→
   136→  return {
   137→    _ulid: input._ulid ?? ulid(),
   138→    slugs: input.slugs ?? [],
   139→    title: input.title,
   140→    content: input.content ?? "",
   141→    status: input.status ?? "draft",
   142→    derived_tasks: input.derived_tasks ?? [],
   143→    derived_specs: input.derived_specs ?? [],
   144→    source_path: input.source_path ?? null,
   145→    created_at: input.created_at ?? now,
   146→    approved_at: input.approved_at ?? null,
   147→    completed_at: input.completed_at ?? null,
   148→    notes: input.notes ?? [],
   149→  };
   150→}
   151→
   152→/**
   153→ * Save a single plan (create or update)
   154→ * AC: @plan-crud ac-1, ac-3 - save plan changes
   155→ * Uses file lock to prevent TOCTOU race on concurrent writes.
   156→ */
   157→export async function savePlan(
   158→  ctx: KspecContext,
   159→  plan: LoadedPlan,
   160→): Promise<void> {
   161→  const plansPath = getPlansFilePath(ctx);
   162→
   163→  // Lock the file to prevent concurrent read-modify-write races
   164→  await withFileLock(plansPath, async () => {
   165→    // Ensure directory exists
   166→    const dir = path.dirname(plansPath);
   167→    await fs.mkdir(dir, { recursive: true });
   168→
   169→    // Load existing plans (inside lock to prevent TOCTOU)
   170→    let plans: Plan[] = [];
   171→    try {
   172→      plans = await loadPlansFromFile(plansPath);
   173→    } catch {
   174→      // File doesn't exist yet, start fresh
   175→    }
   176→
   177→    const cleanPlan = stripPlanMetadata(plan);
   178→
   179→    // Update or add
   180→    const existingIndex = plans.findIndex((p) => p._ulid === plan._ulid);
   181→    if (existingIndex >= 0) {
   182→      plans[existingIndex] = cleanPlan;
   183→    } else {
   184→      plans.push(cleanPlan);
   185→    }
   186→
   187→    // Save back to file
   188→    const plansFile: PlansFile = {
   189→      kynetic_plans: "1.0",
   190→      plans,
   191→    };
   192→
   193→    await writeYamlFilePreserveFormat(plansPath, plansFile);
   194→  });
   195→}
   196→
   197→/**
   198→ * Atomically mutate a plan using the latest on-disk state.
   199→ *
   200→ * The callback receives the current plan value while holding the plan file lock,
   201→ * so concurrent writers do not clobber unrelated fields (for example status vs notes).
   202→ */
   203→export async function mutatePlanAtomically(
   204→  ctx: KspecContext,
   205→  plan: LoadedPlan,
   206→  mutate: (latestPlan: LoadedPlan) => Plan | LoadedPlan | Promise<Plan | LoadedPlan>,
   207→): Promise<LoadedPlan> {
   208→  const plansPath = plan._sourceFile || getPlansFilePath(ctx);
   209→  let updatedPlan: LoadedPlan | undefined;
   210→
   211→  await withFileLock(plansPath, async () => {
   212→    // Ensure directory exists (important for default path in new repos)
   213→    const dir = path.dirname(plansPath);
   214→    await fs.mkdir(dir, { recursive: true });
   215→
   216→    let plans: Plan[] = [];
   217→    try {
   218→      plans = await loadPlansFromFile(plansPath);
   219→    } catch {
   220→      throw new Error(`Plans file not found: ${plansPath}`);
   221→    }
   222→
   223→    const planIndex = plans.findIndex((candidate) => candidate._ulid === plan._ulid);
   224→    if (planIndex === -1) {
   225→      throw new Error(`Plan not found in file: ${plan._ulid}`);
   226→    }
   227→
   228→    const latestPlan: LoadedPlan = {
   229→      ...plans[planIndex],
   230→      _sourceFile: plansPath,
   231→    };
   232→
   233→    const mutatedPlan = await mutate(latestPlan);
   234→    const cleanMutatedPlan = stripPlanMetadata(mutatedPlan);
   235→    plans[planIndex] = cleanMutatedPlan;
   236→
   237→    const plansFile: PlansFile = {
   238→      kynetic_plans: "1.0",
   239→      plans,
   240→    };
   241→    await writeYamlFilePreserveFormat(plansPath, plansFile);
   242→
   243→    updatedPlan = {
   244→      ...cleanMutatedPlan,
   245→      _sourceFile: plansPath,
   246→    };
   247→  });
   248→
   249→  if (!updatedPlan) {
   250→    throw new Error(`Failed to mutate plan atomically: ${plan._ulid}`);
   251→  }
   252→
   253→  return updatedPlan;
   254→}
   255→
   256→/**
   257→ * Delete a plan by ULID
   258→ */
   259→export async function deletePlan(
   260→  ctx: KspecContext,
   261→  planUlid: string,
   262→): Promise<boolean> {
   263→  const plansPath = getPlansFilePath(ctx);
   264→
   265→  // Lock the file to prevent concurrent read-modify-write races
   266→  return withFileLock(plansPath, async () => {
   267→    try {
   268→      const plans = await loadPlansFromFile(plansPath);
   269→
   270→      // Find plan to delete
   271→      const index = plans.findIndex((p) => p._ulid === planUlid);
   272→      if (index < 0) {
   273→        return false;
   274→      }
   275→
   276→      // Remove plan
   277→      plans.splice(index, 1);
   278→
   279→      // Save back
   280→      const plansFile: PlansFile = {
   281→        kynetic_plans: "1.0",
   282→        plans,
   283→      };
   284→
   285→      await writeYamlFilePreserveFormat(plansPath, plansFile);
   286→      return true;
   287→    } catch {
   288→      return false;
   289→    }
   290→  });
   291→}
   292→
   293→/**
   294→ * Filter plans by status
   295→ * AC: @plan-crud ac-7 - list with status filter
   296→ */
   297→export function filterPlansByStatus(
   298→  plans: LoadedPlan[],
   299→  status?: string,
   300→): LoadedPlan[] {
   301→  if (!status) return plans;
   302→  return plans.filter((p) => p.status === status);
   303→}
   304→
   305→/**
   306→ * Get plan statistics
   307→ */
   308→export function getPlanStats(plans: LoadedPlan[]): {
   309→  total: number;
   310→  byStatus: Record<string, number>;
   311→} {
   312→  const byStatus: Record<string, number> = {};
   313→
   314→  for (const plan of plans) {
   315→    byStatus[plan.status] = (byStatus[plan.status] ?? 0) + 1;
   316→  }
   317→
   318→  return {
   319→    total: plans.length,
   320→    byStatus,
   321→  };
   322→}
   323→
